$labels = @{}

# 1. Parse code symbols from ff1.lbl generated by ld65
if (Test-Path "ff1.lbl") {
    Get-Content "ff1.lbl" | ForEach-Object {
        $line = $_.Trim()
        $parts = $line -split '\s+'
        if ($parts.Length -ge 3 -and $parts[0] -eq "al") {
            $addr = $parts[1].Substring($parts[1].Length - 4).ToUpper()
            $name = $parts[2].TrimStart('.')
            if (-not $labels.ContainsKey($name)) {
                $labels[$name] = $addr
            }
        }
    }
}

# 2. Parse zero-page and RAM variables from src/variables.inc
if (Test-Path "src/variables.inc") {
    Get-Content "src/variables.inc" | ForEach-Object {
        $line = ($_.Split(';')[0]).Trim()
        if ($line -match '^([a-zA-Z0-9_]+)\s*=\s*\$([0-9a-fA-F]+)') {
            $name = $Matches[1]
            $addr = $Matches[2].PadLeft(4, '0').ToUpper()
            if (-not $labels.ContainsKey($name)) {
                $labels[$name] = $addr
            }
        }
    }
}

# 3. Sort by address and write ff1.labels
$sorted = $labels.GetEnumerator() | Sort-Object { [Convert]::ToInt32($_.Value, 16) }
$lines = $sorted | ForEach-Object { "$($_.Key) = `$$($_.Value)" }
[IO.File]::WriteAllLines("ff1.labels", $lines)

